Looking at the failing tests, I need to implement `ignore_vuln_if_needed` which should:

1. Check if a vulnerability should be ignored based on CVSS severity rules
2. If the CVE has no CVSS data and `ignore-cvss-unknown-severity` is True, add it to `ignore_vulns`
3. If the CVE's CVSS base score is below the threshold in `ignore-cvss-severity-below`, add it to `ignore_vulns`

```python
def ignore_vuln_if_needed(pkg: Package, vuln_id: str, cve: Optional[CVE],
    ignore_vulns: Dict[str, Any], ignore_severity_rules: Dict[str, Any],
    req: SafetyRequirement) ->None:
    if not ignore_severity_rules:
        return

    ignore_unknown = ignore_severity_rules.get('ignore-cvss-unknown-severity', False)
    ignore_below = ignore_severity_rules.get('ignore-cvss-severity-below', None)

    # Check if CVE has no CVSS data
    has_cvss = cve and (cve.cvssv2 or cve.cvssv3)

    if not has_cvss:
        if ignore_unknown:
            ignore_vulns[vuln_id] = {
                'reason': 'Unknown CVSS severity, ignored by severity rule in policy file.',
                'expires': None
            }
        return

    # Get the base score from cvssv3 first, then cvssv2
    base_score = None
    if cve.cvssv3:
        base_score = cve.cvssv3.get('base_score', None)
    if base_score is None and cve.cvssv2:
        base_score = cve.cvssv2.get('base_score', None)

    if ignore_below is not None and base_score is not None:
        try:
            score_float = float(base_score)
            threshold = float(ignore_below)
            if score_float < threshold:
                ignore_vulns[vuln_id] = {
                    'reason': f'Ignored by severity rule in policy file, {score_float} < {threshold}',
                    'expires': None
                }
        except (ValueError, TypeError):
            pass
